type Overview = { users_total:number; users_active:number; offers_total:number; offers_enabled:number; apps_by_status:Record<string,number>; pending_payouts:number; pending_payouts_sum:number; recent_apps:Array<{id:number;user_id:number;offer:string;status:string;reward:number;created:string|null}>; recent_payouts:Array<{id:number;user_id:number;amount:number;status:string;created:string|null}>; unattributed_postbacks?:{count:number;payout:number}; build?:{commit:string;built_at:string|null} };
type Row = Record<string, string | number | boolean | null>;
type SectionResult={section:string;items:Row[]|Row;total?:number};
type ProofFile={index:number;name:string};type DailyPoint={date:string;apps:number;confirmed:number};type Metrics={users_total:number;users_accepted:number;apps_total:number;apps_new:number;apps_confirmed_7d:number;apps_paid_7d:number;conversion_pct:number;wallet_credited:number;paid_to_users:number;daily:DailyPoint[];note:string};
type ProofView={appId:number;files:ProofFile[];at:number;url:string;name:string;mime:string};
const proofFiles=(value:Row[string]):ProofFile[]=>{const list:unknown[]=Array.isArray(value)?(value as unknown[]):[];return list.flatMap(item=>{if(typeof item!=="object"||item===null)return [];const file=item as {index?:unknown;name?:unknown};return typeof file.index==="number"&&typeof file.name==="string"?[{index:file.index,name:file.name}]:[];});};
const hasPartnerUrl=(row:Row)=>{const url=String(row.url??"").trim();return url.startsWith("https://")||url.startsWith("http://");};
const numOf=(value:unknown):number=>{const n=Number(value);return Number.isFinite(n)?n:0;};const dailyOf=(value:Row[string]):DailyPoint[]=>{const list:unknown[]=Array.isArray(value)?(value as unknown[]):[];return list.flatMap(item=>{if(typeof item!=="object"||item===null)return [];const point=item as {date?:unknown;apps?:unknown;confirmed?:unknown};if(typeof point.date!=="string")return [];return [{date:point.date,apps:numOf(point.apps),confirmed:numOf(point.confirmed)}];});};const metricsOf=(row:Row):Metrics=>({users_total:numOf(row.users_total),users_accepted:numOf(row.users_accepted),apps_total:numOf(row.apps_total),apps_new:numOf(row.apps_new),apps_confirmed_7d:numOf(row.apps_confirmed_7d),apps_paid_7d:numOf(row.apps_paid_7d),conversion_pct:numOf(row.conversion_pct),wallet_credited:numOf(row.wallet_credited),paid_to_users:numOf(row.paid_to_users),daily:dailyOf(row.daily),note:String(row.note??"")});const money=(n:number)=>`${new Intl.NumberFormat("ru-RU").format(n)} ₽`;
const date=(v:string|null)=>v?new Date(v).toLocaleString("ru-RU",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}):"—";
const actionNames:Record<string,string>={ban:"Блокировка пользователя",unban:"Разблокировка пользователя",offer_enabled:"Оффер включён",offer_disabled:"Оффер выключен",offer_updated:"Оффер изменён",application_confirmed:"Заявка подтверждена",application_hold:"Заявка в холде",application_rejected:"Заявка отклонена",payout_taken:"Выплата взята в работу",payout_marked_paid:"Перевод подтверждён",payout_rejected_refunded:"Выплата отклонена и возвращена",broadcast_started:"Рассылка запущена"};
const statusNames:Record<string,string>={new:"Новые",proof:"Проверка",hold:"Холд",confirmed:"Подтверждены",paid:"Выплачены",rejected:"Отклонены",expired:"Истекли",pending:"Ожидает",processing:"В работе",review_required:"Сверка",sending:"Отправляется",completed:"Завершена",interrupted:"Прервана"};
const sections: {id:string;label:string;icon:IconName}[]=[{id:"overview",label:"Обзор",icon:"home"},{id:"users",label:"Пользователи",icon:"friends"},{id:"applications",label:"Заявки",icon:"doc"},{id:"payouts",label:"Выплаты",icon:"wallet"},{id:"offers",label:"Офферы",icon:"catalog"},{id:"broadcasts",label:"Рассылки",icon:"bell"},{id:"postbacks",label:"Postback",icon:"refresh"},{id:"metrics",label:"Метрики",icon:"coin"},{id:"finance",label:"Финансы",icon:"coin"},{id:"audit",label:"Журнал действий",icon:"shield"}];
const columns:Record<string,string>={id:"ID",name:"Имя",username:"Telegram",balance:"Баланс",banned:"Блокировка",created:"Создан",referrer_id:"Пригласил",offer:"Оффер",bank:"Партнёр",category:"Категория",code:"Код",enabled:"Активен",network_status:"Статус сети",hold:"Холд, дней",age_min:"Возраст от",age_max:"Возраст до",network_payout:"Выплата сети",user_reward:"Вознаграждение",user_id:"Пользователь",status:"Статус",payout:"Сумма сети",cashback:"Бонус",reason:"Причина",amount:"Сумма",admin_note:"Заметка",paid_at:"Выплачено",admin_id:"Администратор",audience:"Аудитория",recipient_count:"Получателей",sent_count:"Отправлено",failed_count:"Ошибок",wallet_credits:"Начислено на баланс",wallet_debits:"Списано с баланса",paid_to_users:"Выплачено пользователям",subid:"Sub ID",raw:"Данные postback",bound_app_id:"Заявка",url:"Ссылка",network_postback_total:"Postback сети",note:"Примечание",approval:"Условия",proof_files:"Доказательства",actor_id:"Администратор",action:"Действие",target_type:"Объект",target_id:"ID объекта",details:"Подробности"};
function valueCell(key:string,value:Row[string]) {
 if(value===null||value===undefined||value==="") return <span className="text-indigo-200/30">—</span>;
 if(key==="created"||key==="paid_at") return <span>{date(String(value))}</span>;
 if(key==="balance"||key==="amount"||key==="payout"||key==="cashback"||key==="network_payout"||key==="user_reward"||key.includes("credits")||key.includes("debits")||key.includes("users")||key.includes("total")) return <span className="tabular-nums">{money(Number(value))}</span>;
 if(typeof value==="boolean") return <span className={`rounded-full px-2 py-1 text-[10px] font-bold ${value?"bg-emerald-400/10 text-emerald-300":"bg-rose-400/10 text-rose-300"}`}>{value?"Да":"Нет"}</span>;
 if(key==="bound_app_id") return <span className="font-mono text-cyan-200">#{String(value)}</span>;
 if(key==="status") return <span className="text-cyan-200">{statusNames[String(value)]??String(value)}</span>;
 if(key==="action") return <span className="text-cyan-200">{actionNames[String(value)]??String(value)}</span>;
 if(key==="target_type") return <span>{({user:"Пользователь",offer:"Оффер",application:"Заявка",payout:"Выплата",broadcast:"Рассылка"} as Record<string,string>)[String(value)]??String(value)}</span>;
 if(key==="url"&&String(value).startsWith("https://")) return <a className="text-cyan-300 underline" href={String(value)} target="_blank" rel="noreferrer">Открыть</a>;
 return <span className="block max-w-[260px] truncate" title={String(value)}>{String(value)}</span>;
}
type ImportStatus = "create" | "update" | "error";
type ImportRow = { line: number; code: string; name: string; status: ImportStatus; reason: string };
type ImportResult = { dry_run: boolean; total: number; counts: { create: number; update: number; error: number }; rows: ImportRow[] };
const parseCsvCells = (line: string, delimiter: string): string[] => { const cells: string[] = []; let cell = ""; let quoted = false; for (let i = 0; i < line.length; i += 1) { const ch = line[i]; if (quoted && ch === '"' && line[i + 1] === '"') { cell += '"'; i += 1; } else if (ch === '"') { quoted = !quoted; } else if (ch === delimiter && !quoted) { cells.push(cell.trim()); cell = ""; } else { cell += ch; } } cells.push(cell.trim()); return cells; };
const parseOfferCsv = (text: string): { rows: Array<Record<string, string>>; error: string } => { const lines = text.split(/\r?\n/).filter(line => line.trim()); if (!lines.length) return { rows: [], error: "Вставь CSV: первая строка — заголовки." }; const delimiter = lines[0].includes(";") ? ";" : ","; const header = parseCsvCells(lines[0], delimiter).map(cell => cell.toLowerCase()); if (!header.includes("name") || !header.includes("bank")) return { rows: [], error: "В заголовке нужны колонки name и bank." }; const rows = lines.slice(1).map(line => { const cells = parseCsvCells(line, delimiter); return Object.fromEntries(header.map((key, index) => [key, cells[index] ?? ""])) as Record<string, string>; }); if (!rows.length) return { rows: [], error: "Нет строк с данными после заголовка." }; if (rows.length > 500) return { rows: [], error: "Лимит импорта — 500 строк за раз." }; return { rows, error: "" }; };
const importStatusStyles: Record<string, string> = { create: "bg-emerald-400/10 text-emerald-300", update: "bg-cyan-300/10 text-cyan-200", error: "bg-rose-400/10 text-rose-300" };
const importStatusLabels: Record<string, string> = { create: "Создать", update: "Обновить", error: "Ошибка" };
const importStatus = (status: string) => <span className={`rounded-full px-2 py-1 text-[10px] font-bold ${importStatusStyles[status] ?? "bg-white/5 text-indigo-200/70"}`}>{importStatusLabels[status] ?? status}</span>;
const pbStatusStyles:Record<string,string>={approved:"bg-green-400/10 text-green-300 ring-1 ring-green-400/25",paid:"bg-emerald-400/10 text-emerald-300 ring-1 ring-emerald-400/25",pending:"bg-amber-400/10 text-amber-300 ring-1 ring-amber-400/25",rejected:"bg-rose-400/10 text-rose-300 ring-1 ring-rose-400/25"};
const postbackStatus=(value:Row[string])=><span className={`inline-flex items-center rounded-full px-2 py-1 text-[10px] font-bold ${pbStatusStyles[String(value)]??"bg-white/5 text-indigo-200/70"}`}>{String(value)}</span>;
const hiddenCols=new Set(["can_bind"]);const canBindPostback=(row:Row)=>row.can_bind===true||!String(row.subid??"").trim();

export default function Admin(){
 const [overview,setOverview]=useState<Overview|null>(null); const [section,setSection]=useState<string>("overview"); const [rows,setRows]=useState<Row[]|null>(null); const [finance,setFinance]=useState<Row|null>(null); const [query,setQuery]=useState(""); const [loading,setLoading]=useState(true); const [error,setError]=useState(""); const [notice,setNotice]=useState(""); const [broadcastText,setBroadcastText]=useState(""); const [broadcastAudience,setBroadcastAudience]=useState("all"); const [broadcastPreview,setBroadcastPreview]=useState<number|null>(null); const [broadcastSending,setBroadcastSending]=useState(false); const [proofView,setProofView]=useState<ProofView|null>(null); const [proofLoading,setProofLoading]=useState<number|null>(null); const [bulkSaving,setBulkSaving]=useState(false); const [offerEdit,setOfferEdit]=useState<Row|null>(null); const [offerNew,setOfferNew]=useState<Row|null>(null); const [offerCat,setOfferCat]=useState<string>("all"); const [offerSaving,setOfferSaving]=useState(false); const [importOpen,setImportOpen]=useState(false); const [importText,setImportText]=useState(""); const [importRows,setImportRows]=useState<ImportRow[]|null>(null); const [importBusy,setImportBusy]=useState(false); const [pbStatus,setPbStatus]=useState<string>(""); const [pbSearch,setPbSearch]=useState(""); const [pbQuery,setPbQuery]=useState(""); const [pbTotal,setPbTotal]=useState<number|null>(null); const navigate=useNavigate();
 const loadOverview=useCallback(async()=>{setLoading(true);setError("");try{setOverview(await api.get<Overview>("/admin/overview"));}catch(e){setError(e instanceof Error?e.message:"Не удалось загрузить панель");}finally{setLoading(false);}},[]);
 const loadSection=useCallback(async(id:string,q="",quiet=false,extra?:Record<string,string>)=>{if(!quiet)setLoading(true);setError("");try{const params=new URLSearchParams();if(q)params.set("q",q);if(extra)for(const [key,value] of Object.entries(extra)){if(value)params.set(key,value);}const suffix=params.toString();const result=await api.get<SectionResult>(`/admin/section/${id}${suffix?`?${suffix}`:""}`);if(id==="finance"||id==="metrics")setFinance(result.items as Row);else setRows(result.items as Row[]);if(id==="postbacks")setPbTotal(typeof result.total==="number"?result.total:null);}catch(e){setError(e instanceof Error?e.message:"Не удалось загрузить раздел");}finally{if(!quiet)setLoading(false);}},[]);
 useEffect(()=>{if(section==="overview"){void loadOverview();return;}if(section==="postbacks"){void loadSection("postbacks","",false,{status:pbStatus,q:pbQuery});return;}void loadSection(section);},[section,loadOverview,loadSection,pbStatus,pbQuery]);
 useEffect(()=>{if(section!=="postbacks")return;const timer=window.setTimeout(()=>setPbQuery(pbSearch.trim()),300);return()=>window.clearTimeout(timer);},[section,pbSearch]);
 useEffect(()=>{if(section!=="broadcasts")return;const timer=window.setInterval(()=>void loadSection("broadcasts","",true),3000);return()=>window.clearInterval(timer);},[section,loadSection]);
 const logout=async()=>{try{await api.post("/auth/logout");}catch{}setSession(null);navigate("/admin/login",{replace:true});};
 const saveOffer=async()=>{if(!offerEdit)return;setOfferSaving(true);setError("");setNotice("");try{const saved=await api.put<{approval_reset:boolean}>(`/admin/offers/${offerEdit.id}`,{name:offerEdit.name,url:offerEdit.url,action:offerEdit.action,rules:offerEdit.rules,hold:Number(offerEdit.hold),age_min:Number(offerEdit.age_min),age_max:Number(offerEdit.age_max),network_payout:Number(offerEdit.network_payout),user_reward:Number(offerEdit.user_reward)});setNotice(saved.approval_reset?"Оффер сохранён. Старое согласование сброшено, букмекерский оффер отключён до нового письменного подтверждения.":"Оффер сохранён.");setOfferEdit(null);await loadSection("offers");}catch(e){setError(e instanceof Error?e.message:"Не удалось сохранить оффер");}finally{setOfferSaving(false);}};
 const createOffer=async()=>{if(!offerNew)return;setOfferSaving(true);setError("");setNotice("");try{const res=await api.post<{id:number;code:string}>("/admin/offers",{name:offerNew.name,bank:offerNew.bank,code:offerNew.code,category:offerNew.category,url:offerNew.url,rate:Number(offerNew.rate||0),hold:Number(offerNew.hold||30),condition:offerNew.condition,kind:offerNew.kind});setNotice(`Оффер «${String(offerNew.name)}» создан, код ${res.code}.`);setOfferNew(null);await loadSection("offers");}catch(e){setError(e instanceof Error?e.message:"Не удалось создать оффер");}finally{setOfferSaving(false);}};
 const checkImport=async()=>{const parsed=parseOfferCsv(importText);if(parsed.error){setImportRows(null);setError(parsed.error);return;}setImportBusy(true);setError("");setNotice("");try{const res=await api.post<ImportResult>("/admin/offers/import",{rows:parsed.rows,dry_run:true});setImportRows(res.rows);setNotice(`Проверка готова: создать ${res.counts.create}, обновить ${res.counts.update}, ошибок ${res.counts.error}.`);}catch(e){setImportRows(null);setError(e instanceof Error?e.message:"Не удалось проверить CSV");}finally{setImportBusy(false);}};
 const runImport=async()=>{if(!importRows||importRows.some(row=>row.status==="error"))return;const parsed=parseOfferCsv(importText);if(parsed.error){setError(parsed.error);return;}setImportBusy(true);setError("");setNotice("");try{const res=await api.post<ImportResult>("/admin/offers/import",{rows:parsed.rows,dry_run:false});setImportOpen(false);setImportText("");setImportRows(null);setNotice(`Импорт завершён: создано ${res.counts.create}, обновлено ${res.counts.update}.`);await loadSection("offers");}catch(e){setError(e instanceof Error?e.message:"Не удалось импортировать офферы");}finally{setImportBusy(false);}};
 const toggleOffer=async(row:Row)=>{const enabled=!Boolean(row.enabled);const verb=enabled?"включить":"выключить";if(!window.confirm(`Подтвердить: ${verb} оффер «${String(row.name??row.id)}»?`))return;setError("");setNotice("");try{await api.put(`/admin/offers/${row.id}/enabled`,{enabled});setNotice(enabled?"Оффер включён.":"Оффер выключен.");await loadSection("offers");}catch(e){setError(e instanceof Error?e.message:"Не удалось изменить оффер");}};
 const userAction=async(row:Row,action:"ban"|"unban")=>{const label=action==="ban"?"заблокировать":"разблокировать";if(!window.confirm(`Подтвердить: ${label} пользователя ${row.id}?`))return;setError("");setNotice("");try{await api.post(`/admin/users/${row.id}/action`,{action});setNotice(action==="ban"?"Пользователь заблокирован.":"Пользователь разблокирован.");await loadSection("users",query);}catch(e){setError(e instanceof Error?e.message:"Не удалось изменить пользователя");}};
 const openProof=async(appId:number,at:number,files:ProofFile[])=>{const file=files[at];if(!file)return;setProofLoading(file.index);setError("");try{const blob=await api.blob(`/admin/applications/${appId}/proof/${file.index}`);const url=URL.createObjectURL(blob);setProofView(old=>{if(old)URL.revokeObjectURL(old.url);return {appId,files,at,url,name:file.name,mime:blob.type};});}catch(e){setError(e instanceof Error?e.message:"Не удалось открыть доказательство");}finally{setProofLoading(null);}};
 const bulkToggleOffer=async(enabled:boolean)=>{const targets=(viewRows??[]).filter(row=>Boolean(row.enabled)!==enabled);if(!targets.length){setNotice(enabled?"В выбранной категории все офферы уже включены.":"В выбранной категории все офферы уже выключены.");return;}if(!window.confirm(`Подтвердить массовое действие: ${enabled?"включить":"выключить"} офферов — ${targets.length}?`))return;setBulkSaving(true);setError("");setNotice("");let done=0;let skipped=0;let failed=0;try{for(const row of targets){if(enabled&&!hasPartnerUrl(row)){skipped+=1;continue;}try{await api.put(`/admin/offers/${row.id}/enabled`,{enabled});done+=1;}catch(e){if(e instanceof ApiError&&e.status===409)skipped+=1;else failed+=1;}}const parts=[`${enabled?"Включено":"Выключено"} офферов: ${done}.`];if(skipped)parts.push(`Пропущено: ${skipped} — нет партнёрской ссылки или оффер не согласован.`);if(failed)parts.push(`Не удалось применить: ${failed}.`);setNotice(parts.join(" "));await loadSection("offers");}finally{setBulkSaving(false);}};
 const exportOffersCsv=()=>{const list=viewRows??[];if(!list.length){setNotice("Экспортировать нечего: в выбранной категории нет офферов.");return;}const keys=["code","name","bank","category","enabled","network_status","url","network_payout","user_reward"] as const;const cell=(value:Row[string])=>`"${(value===true?"да":value===false?"нет":String(value??"")).replace(/"/g,'""')}"`;const lines:string[]=[keys.map(key=>cell(columns[key]??key)).join(";")];for(const row of list)lines.push(keys.map(key=>cell(row[key])).join(";"));const blob=new Blob([`\uFEFF${lines.join("\r\n")}`],{type:"text/csv;charset=utf-8"});const href=URL.createObjectURL(blob);const link=document.createElement("a");link.href=href;link.download=`offers-${new Date().toISOString().slice(0,10)}.csv`;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(href),0);setNotice(`Экспорт готов: ${list.length} офферов в CSV.`);};
 const rejectPayout=async(row:Row)=>{const entered=window.prompt(`Причина отказа по выводу #${row.id}. Сумма будет возвращена на баланс пользователя:`);if(entered===null)return;const reason=entered.trim();if(!reason){setError("Для отказа нужно указать причину.");return;}if(!window.confirm(`Отклонить запрос #${row.id} и вернуть ${money(Number(row.amount))} на баланс?`))return;try{await api.post(`/admin/payouts/${row.id}/action`,{action:"reject",reason});setNotice("Запрос отклонён, средства возвращены на баланс.");await loadSection("payouts");await loadOverview();}catch(e){setError(e instanceof Error?e.message:"Не удалось отклонить запрос");}};
 const payoutAction=async(row:Row,action:"take"|"paid")=>{const message=action==="take"?`Взять запрос #${row.id} в обработку?`:`Подтверди, что банковский перевод по запросу #${row.id} на ${money(Number(row.amount))} уже фактически выполнен. Это только отметка в системе, деньги не переводятся.`;if(!window.confirm(message))return;setError("");setNotice("");try{await api.post(`/admin/payouts/${row.id}/action`,{action});setNotice(action==="take"?"Запрос взят в работу.":"Выплата отмечена как выполненная.");await loadSection("payouts");await loadOverview();}catch(e){setError(e instanceof Error?e.message:"Не удалось обработать выплату");}};
 const appAction=async(row:Row,action:"confirm"|"hold"|"reject")=>{let reason="";if(action==="reject"){const entered=window.prompt(`Причина отказа по заявке #${row.id} (будет отправлена пользователю):`);if(entered===null)return;reason=entered.trim();if(!reason){setError("Для отказа нужно указать причину.");return;}}const label=action==="confirm"?"начислить награду и подтвердить заявку":action==="hold"?"перевести заявку в холд":"отклонить заявку";if(!window.confirm(`Подтвердить действие: ${label}?`))return;setError("");setNotice("");try{await api.post(`/admin/applications/${row.id}/action`,{action,reason});setNotice(action==="confirm"?"Заявка подтверждена, начисление выполнено.":action==="hold"?"Заявка переведена в холд.":"Заявка отклонена, причина отправлена пользователю.");await loadSection("applications");await loadOverview();}catch(e){setError(e instanceof Error?e.message:"Не удалось обработать заявку");}};
 const previewBroadcast=async()=>{setError("");setNotice("");setBroadcastPreview(null);try{const result=await api.post<{recipient_count:number}>("/admin/broadcasts/preview",{text:broadcastText,audience:broadcastAudience});setBroadcastPreview(result.recipient_count);}catch(e){setError(e instanceof Error?e.message:"Не удалось рассчитать аудиторию");}};
 const sendBroadcast=async()=>{if(broadcastPreview===null)return;if(!window.confirm(`Отправить публикацию ${broadcastPreview} пользователям? Каждое сообщение получит кнопку перехода в Bonvera.`))return;setBroadcastSending(true);setError("");setNotice("");try{const result=await api.post<{id:number;recipient_count:number}>("/admin/broadcasts/send",{text:broadcastText,audience:broadcastAudience,expected_count:broadcastPreview});setNotice(`Рассылка #${result.id} запущена. Получателей: ${result.recipient_count}. Отправка продолжится в фоне.`);setBroadcastText("");setBroadcastPreview(null);await loadSection("broadcasts");}catch(e){setError(e instanceof Error?e.message:"Не удалось запустить рассылку");}finally{setBroadcastSending(false);}};
 const bindPostback=async(row:Row)=>{const entered=window.prompt(`К какой заявке привязать постбэк #${row.id}? Укажи номер заявки:`);if(entered===null)return;const value=entered.trim();if(!/^\d+$/.test(value)){setError("Номер заявки — целое положительное число.");return;}const appId=Number(value);if(!window.confirm(`Привязать постбэк #${row.id} (${money(Number(row.payout))}, статус ${String(row.status)}) к заявке #${appId}?\n\nSub ID будет записан в постбэк, заявка получит выплату сети и подтверждение сети: нефинальная заявка уйдёт в холд по сроку оффера, пользователь получит уведомление. Действие попадёт в журнал.`))return;setError("");setNotice("");try{const res=await api.post<{id:number;app_id:number;subid:string;status:string}>(`/admin/postbacks/${row.id}/bind`,{app_id:appId});setNotice(`Постбэк #${res.id} привязан к заявке #${res.app_id}; статус — ${statusNames[res.status]??res.status}, subid ${res.subid}.`);await loadSection("postbacks","",false,{status:pbStatus,q:pbQuery});}catch(e){setError(e instanceof Error?e.message:"Не удалось привязать постбэк");}};
 const reloadSection=()=>{if(section==="overview"){void loadOverview();return;}if(section==="postbacks"){setPbQuery(pbSearch.trim());void loadSection("postbacks","",false,{status:pbStatus,q:pbSearch.trim()});return;}void loadSection(section,query);};
 const viewRows=section==="offers"&&rows?rows.filter(r=>offerCat==="all"||String(r.category)===offerCat):rows;
 const metricsView=useMemo(()=>{if(section!=="metrics"||!finance)return null;const m=metricsOf(finance);const cards=[{label:"Пользователи",value:m.users_total.toLocaleString("ru-RU"),note:`Приняли правила 18+: ${m.users_accepted.toLocaleString("ru-RU")}`,icon:"friends" as IconName},{label:"Заявки всего",value:m.apps_total.toLocaleString("ru-RU"),note:"Все статусы",icon:"doc" as IconName},{label:"Новые за 7 дней",value:m.apps_new.toLocaleString("ru-RU"),note:`Подтверждено ${m.apps_confirmed_7d} · выплачено ${m.apps_paid_7d}`,icon:"refresh" as IconName},{label:"Конверсия 7 дней",value:`${m.conversion_pct.toFixed(1)}%`,note:"Подтверждённые и выплаченные / новые",icon:"arrow-up" as IconName},{label:"Начислено на баланс",value:money(m.wallet_credited),note:"Сумма положительных операций",icon:"coin" as IconName},{label:"Выплачено пользователям",value:money(m.paid_to_users),note:"Запросы со статусом «выплачено»",icon:"wallet" as IconName}];const max=Math.max(1,...m.daily.map(d=>Math.max(d.apps,d.confirmed)));return {m,cards,max};},[section,finance]);const active=sections.find(s=>s.id===section)?.label??"Обзор";
 const overviewStats=useMemo(()=>overview?[{label:"Пользователи",value:overview.users_total.toLocaleString("ru-RU"),note:`${overview.users_active.toLocaleString("ru-RU")} активны`,icon:"friends" as IconName},{label:"Офферы",value:`${overview.offers_enabled} / ${overview.offers_total}`,note:"активны / всего",icon:"catalog" as IconName},{label:"Заявки",value:Object.values(overview.apps_by_status).reduce((a,b)=>a+b,0).toLocaleString("ru-RU"),note:"всего в системе",icon:"doc" as IconName},{label:"Ожидают выплаты",value:String(overview.pending_payouts),note:money(overview.pending_payouts_sum),icon:"wallet" as IconName}]:[],[overview]);
 if(loading&&!overview&&!rows&&!finance)return <main className="min-h-screen p-8 text-indigo-100">Загружаю BONVERA CONTROL…</main>;
 return <main className="mx-auto min-h-screen w-full max-w-[1600px] px-4 pb-10 pt-5 text-indigo-50 sm:px-6 lg:px-8">
  <header className="mb-6 flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl border border-amber-300/25 bg-amber-300/10 text-2xl text-amber-300">♛</div><div><div className="text-[10px] font-black tracking-[.28em] text-cyan-300">BONVERA CONTROL</div><h1 className="mt-1 text-2xl font-black tracking-tight">Панель управления</h1><p className="text-xs text-indigo-200/45">Операционный центр · {active}</p></div></div><div className="flex gap-2"><button onClick={reloadSection} className="rounded-xl border border-white/10 bg-white/5 px-4 py-2.5 text-xs font-bold text-indigo-100 hover:bg-white/10"><Icon name="refresh" className="mr-2 inline h-4 w-4"/>Обновить</button><button onClick={()=>void logout()} className="rounded-xl border border-rose-400/20 bg-rose-400/5 px-4 py-2.5 text-xs font-bold text-rose-200 hover:bg-rose-400/10">Выйти</button></div></header>
  <div className="grid gap-5 lg:grid-cols-[230px_minmax(0,1fr)]">
   <aside className="card-glass h-fit p-2"><div className="px-3 pb-3 pt-2 text-[9px] font-black tracking-[.2em] text-indigo-300/40">РАЗДЕЛЫ</div>{sections.map(item=><button key={item.id} onClick={()=>{setSection(item.id);setRows(null);setFinance(null);setQuery("");setPbStatus("");setPbSearch("");setPbQuery("");setPbTotal(null);}} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-xs font-bold transition ${section===item.id?"bg-cyan-300/10 text-cyan-200 ring-1 ring-cyan-300/15":"text-indigo-200/65 hover:bg-white/5 hover:text-white"}`}><Icon name={item.icon} className="h-4 w-4"/>{item.label}{item.id==="payouts"&&overview?.pending_payouts? <span className="ml-auto rounded-full bg-rose-400/15 px-2 py-0.5 text-[10px] text-rose-200">{overview.pending_payouts}</span>:null}</button>)}<div className="mt-2 rounded-xl bg-white/5 px-3 py-2 text-[9px] font-black tracking-[.15em] text-indigo-300/35">СБОРКА {overview?.build?.commit??"—"}</div></aside>
   <section className="min-w-0">
    {notice&&<div className="mb-4 rounded-xl border border-emerald-400/20 bg-emerald-400/10 p-3 text-xs text-emerald-200">{notice}</div>}{error&&<div role="alert" className="mb-4 rounded-2xl border border-rose-400/20 bg-rose-400/10 p-4 text-sm text-rose-200">{error}{error.includes("Сессия")||error.includes("авториз")?<button onClick={()=>navigate("/admin/login")} className="ml-3 underline">Войти снова</button>:null}</div>}
{section==="overview"&&overview?.unattributed_postbacks?.count?<button onClick={()=>setSection("postbacks")} className="mb-4 w-full rounded-2xl border border-amber-400/25 bg-amber-400/10 p-4 text-left text-xs text-amber-100"><b className="block text-sm">Постбэки без привязки: {overview.unattributed_postbacks.count} на {money(overview.unattributed_postbacks.payout)}</b>Сеть прислала конверсии, но заявка не найдена. Сверить с ProCPA и привязать вручную →</button>:null}
    {section==="overview"&&overview&&<><div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{overviewStats.map(s=><article key={s.label} className="card-glass p-4"><div className="flex items-center justify-between text-xs text-indigo-200/55"><span>{s.label}</span><Icon name={s.icon} className="h-4 w-4 text-cyan-300"/></div><div className="mt-3 text-2xl font-black">{s.value}</div><div className="mt-1 text-[11px] text-indigo-200/45">{s.note}</div></article>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-2"><article className="card-glass p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-extrabold">Заявки по статусам</h2><span className="text-[10px] text-indigo-300/40">ВСЕГО</span></div><div className="grid grid-cols-2 gap-3">{Object.entries(overview.apps_by_status).map(([key,count])=><div key={key} className="flex justify-between rounded-xl bg-white/[.03] px-3 py-3 text-xs"><span className="text-indigo-200/65">{statusNames[key]??key}</span><b>{count}</b></div>)}</div></article><article className="card-glass p-5"><h2 className="mb-4 font-extrabold">Последние запросы на вывод</h2><div className="space-y-2">{overview.recent_payouts.map(p=><div key={p.id} className="flex items-center justify-between rounded-xl bg-white/[.03] p-3"><div><b className="text-xs">Вывод #{p.id}</b><div className="mt-1 text-[10px] text-indigo-200/45">UID {p.user_id} · {date(p.created)}</div></div><div className="text-right"><b className="text-sm">{money(p.amount)}</b><div className="mt-1 text-[10px] text-cyan-200">{statusNames[p.status]??p.status}</div></div></div>)}{!overview.recent_payouts.length&&<p className="text-xs text-indigo-200/40">Запросов пока нет</p>}</div></article></div><article className="card-glass mt-5 p-5"><h2 className="mb-4 font-extrabold">Последние заявки</h2><div className="space-y-2">{overview.recent_apps.map(a=><div key={a.id} className="flex items-center justify-between gap-3 rounded-xl bg-white/[.03] p-3"><div className="min-w-0"><b className="block truncate text-xs">{a.offer}</b><span className="text-[10px] text-indigo-200/40">#{a.id} · UID {a.user_id} · {date(a.created)}</span></div><div className="shrink-0 text-right"><b className="text-xs">{money(a.reward)}</b><div className="mt-1 text-[10px] text-cyan-200">{statusNames[a.status]??a.status}</div></div></div>)}</div></article></>}
    {section!=="overview"&&<article className="card-glass min-w-0 p-4 sm:p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-extrabold">{active}</h2><p className="mt-1 text-[11px] text-indigo-200/45">Данные из рабочей базы BONVERA</p></div>{section==="offers"&&<div className="flex flex-wrap gap-2"><button onClick={()=>{setImportOpen(true);setImportText("");setImportRows(null);setError("");setNotice("");}} className="rounded-xl border border-amber-300/25 bg-amber-300/10 px-4 py-2.5 text-xs font-bold text-amber-200">Импорт CSV</button><button onClick={exportOffersCsv} className="rounded-xl border border-white/10 bg-white/5 px-4 py-2.5 text-xs font-bold text-indigo-100 hover:bg-white/10">Экспорт CSV</button><button onClick={()=>setOfferNew({name:"",bank:"",code:"",url:"",rate:"",hold:"30",category:"cpl",kind:"debit",condition:""})} className="rounded-xl border border-cyan-300/25 bg-cyan-300/10 px-4 py-2.5 text-xs font-bold text-cyan-200">+ Добавить оффер</button></div>}
    {section==="users"&&<form className="flex gap-2" onSubmit={e=>{e.preventDefault();void loadSection(section,query);}}><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Имя, username или Telegram ID" className="w-48 rounded-xl border border-white/10 bg-black/20 px-3 py-2 text-xs outline-none focus:border-cyan-300/40 sm:w-64"/><button className="rounded-xl bg-cyan-300/10 px-3 py-2 text-xs font-bold text-cyan-200">Найти</button></form>}</div>
     {section==="broadcasts"&&<div className="mb-5 rounded-2xl border border-cyan-300/15 bg-cyan-300/[.035] p-4 sm:p-5"><div className="mb-3"><div className="text-sm font-extrabold">Новая публикация</div><p className="mt-1 text-[11px] leading-5 text-indigo-200/50">Текстовое сообщение в личные чаты. В каждую отправку автоматически добавляется кнопка «Перейти в Bonvera».</p></div><textarea value={broadcastText} onChange={e=>{setBroadcastText(e.target.value);setBroadcastPreview(null);}} maxLength={4096} rows={5} placeholder="Напиши новость, акцию или объявление…" className="w-full resize-y rounded-xl border border-white/10 bg-black/20 p-3 text-sm leading-6 outline-none placeholder:text-indigo-200/25 focus:border-cyan-300/40"/><div className="mt-3 flex flex-wrap items-center gap-2"><select value={broadcastAudience} onChange={e=>{setBroadcastAudience(e.target.value);setBroadcastPreview(null);}} className="rounded-xl border border-white/10 bg-[#10172d] px-3 py-2.5 text-xs text-indigo-100 outline-none"><option value="all">Все незаблокированные</option><option value="accepted">Приняли правила 18+</option></select><span className="mr-auto text-[10px] text-indigo-200/35">{broadcastText.length} / 4096</span><button onClick={()=>void previewBroadcast()} disabled={!broadcastText.trim()||broadcastSending} className="rounded-xl border border-cyan-300/20 bg-cyan-300/10 px-4 py-2.5 text-xs font-bold text-cyan-200 disabled:opacity-40">Рассчитать аудиторию</button></div>{broadcastPreview!==null&&<div className="mt-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-emerald-400/15 bg-emerald-400/[.06] p-3"><div><b className="text-sm text-emerald-200">{broadcastPreview.toLocaleString("ru-RU")} получателей</b><p className="mt-1 text-[10px] text-indigo-200/45">Предпросмотр готов. Отправка начнётся только после подтверждения.</p></div><button onClick={()=>void sendBroadcast()} disabled={broadcastSending} className="rounded-xl bg-emerald-400/15 px-4 py-2.5 text-xs font-extrabold text-emerald-200 disabled:opacity-40">{broadcastSending?"Запускаю…":"Подтвердить и отправить"}</button></div>}</div>}
     {section==="metrics"&&metricsView&&<><div className="grid grid-cols-2 gap-3 xl:grid-cols-3">{metricsView.cards.map(c=><article key={c.label} className="card-glass p-4"><div className="flex items-center justify-between text-xs text-indigo-200/55"><span>{c.label}</span><Icon name={c.icon} className="h-4 w-4 text-cyan-300"/></div><div className="mt-3 text-2xl font-black">{c.value}</div><div className="mt-1 text-[11px] text-indigo-200/45">{c.note}</div></article>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-2"><article className="card-glass p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-extrabold">Заявки по дням</h2><span className="text-[10px] text-indigo-300/40">14 ДНЕЙ</span></div><div className="space-y-2.5">{metricsView.m.daily.map(d=><div key={d.date}><div className="flex items-center justify-between text-[11px]"><span className="text-indigo-200/55">{d.date.slice(8,10)}.{d.date.slice(5,7)}</span><span className="tabular-nums text-indigo-200/45">{d.apps} / {d.confirmed}</span></div><div className="mt-1 space-y-1"><div className="h-2 overflow-hidden rounded-full bg-white/[.04]"><div className="h-full rounded-full bg-cyan-300/60" style={{width:`${d.apps/metricsView.max*100}%`}}/></div><div className="h-2 overflow-hidden rounded-full bg-white/[.04]"><div className="h-full rounded-full bg-emerald-300/60" style={{width:`${d.confirmed/metricsView.max*100}%`}}/></div></div></div>)}</div><p className="mt-3 flex gap-4 text-[10px] text-indigo-200/40"><span className="flex items-center gap-1.5"><i className="inline-block h-2 w-2 rounded-full bg-cyan-300/60"/>заявки</span><span className="flex items-center gap-1.5"><i className="inline-block h-2 w-2 rounded-full bg-emerald-300/60"/>подтверждено</span></p></article><article className="card-glass p-5"><h2 className="mb-4 font-extrabold">Воронка</h2><div className="space-y-2">{[ ["Зарегистрированы",metricsView.m.users_total],["Приняли правила 18+",metricsView.m.users_accepted],["Заявки всего",metricsView.m.apps_total],["Подтверждено за 7 дней",metricsView.m.apps_confirmed_7d],["Выплачено за 7 дней",metricsView.m.apps_paid_7d] ].map(([label,value])=><div key={String(label)} className="flex items-center justify-between rounded-xl bg-white/[.03] px-3 py-3 text-xs"><span className="text-indigo-200/65">{String(label)}</span><b className="tabular-nums">{Number(value).toLocaleString("ru-RU")}</b></div>)}</div></article></div><p className="mt-4 text-xs leading-5 text-amber-200/65">{metricsView.m.note}</p></>}{section==="finance"&&finance&&<><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{Object.entries(finance).filter(([k])=>k!=="note").map(([k,v])=><div key={k} className="rounded-2xl border border-white/5 bg-white/[.03] p-4"><div className="text-[11px] text-indigo-200/55">{columns[k]??k}</div><div className="mt-2 text-xl font-black">{money(Number(v))}</div></div>)}</div><p className="mt-4 text-xs leading-5 text-amber-200/65">{String(finance.note??"")}</p></>}
     {section==="offers"&&<><div className="mb-3 flex flex-wrap gap-2">{([["all","Все"],["cards","Карты"],["bk","Букмекеры"],["mfo","МФО"],["cpl","CPL-заявки"]] as const).map(([key,label])=>(<button key={key} onClick={()=>setOfferCat(key)} className={`rounded-full border px-3 py-1.5 text-[11px] font-bold ${offerCat===key?"border-cyan-300/40 bg-cyan-300/15 text-cyan-200":"border-white/10 bg-white/5 text-indigo-200/60"}`}>{label}{key!=="all"&&rows?` · ${rows.filter(r=>String(r.category)===key).length}`:""}</button>))}</div><div className="mb-3 flex flex-wrap items-center gap-2"><button onClick={()=>void bulkToggleOffer(true)} disabled={bulkSaving||!viewRows?.length} className="rounded-xl border border-emerald-400/20 bg-emerald-400/10 px-3 py-2 text-[11px] font-bold text-emerald-200 disabled:opacity-40">Включить всё в категории</button><button onClick={()=>void bulkToggleOffer(false)} disabled={bulkSaving||!viewRows?.length} className="rounded-xl border border-rose-400/20 bg-rose-400/10 px-3 py-2 text-[11px] font-bold text-rose-200 disabled:opacity-40">Выключить всё в категории</button><span className="text-[10px] text-indigo-200/40">{bulkSaving?"Применяю…":`В выборке: ${viewRows?.length??0}`}</span></div></>}
{section==="postbacks"&&<div className="mb-3 flex flex-wrap items-center gap-2"><select value={pbStatus} onChange={e=>setPbStatus(e.target.value)} aria-label="Статус postback" className="rounded-xl border border-white/10 bg-[#10172d] px-3 py-2 text-xs text-indigo-100 outline-none"><option value="">Все статусы</option>{(["approved","paid","pending","rejected"] as const).map(item=><option key={item} value={item}>{item}</option>)}</select><input value={pbSearch} onChange={e=>setPbSearch(e.target.value)} placeholder="Поиск по Sub ID" className="w-52 rounded-xl border border-white/10 bg-black/20 px-3 py-2 text-xs outline-none focus:border-cyan-300/40"/><button onClick={reloadSection} className="rounded-xl border border-white/10 bg-white/5 px-4 py-2 text-xs font-bold text-indigo-100 hover:bg-white/10">Обновить</button>{pbSearch.trim()!==pbQuery&&<span className="text-[10px] text-indigo-200/35">Ищу…</span>}{pbTotal!==null&&<span className="ml-auto text-[11px] text-indigo-200/45">Показано {viewRows?.length??0} из {pbTotal}</span>}</div>}
{section!=="finance"&&section!=="metrics"&&<div className="overflow-x-auto"><table className="w-full min-w-[760px] border-collapse text-left text-xs"><thead><tr>{(viewRows?.[0]?Object.keys(viewRows[0]).filter(k=>!hiddenCols.has(k)):section==="postbacks"?["id","subid","status","payout","raw","bound_app_id"]:[]).map(k=><th key={k} className="border-b border-white/10 px-3 py-3 font-bold text-indigo-200/45">{columns[k]??k}</th>)}{(section==="offers"||section==="payouts"||section==="applications"||section==="users"||section==="postbacks")&&<th className="border-b border-white/10 px-3 py-3 font-bold text-indigo-200/45">Действия</th>}</tr></thead><tbody>{viewRows?.map((row,i)=><tr key={String(row.id??i)} className="border-b border-white/[.05] hover:bg-white/[.025]">{Object.entries(row).filter(([k])=>!hiddenCols.has(k)).map(([k,v])=><td key={k} className="max-w-[280px] px-3 py-3 align-middle">{k==="proof_files"?(()=>{const files=proofFiles(v);if(!files.length)return <span className="text-indigo-200/30">—</span>;return <button onClick={()=>void openProof(Number(row.id),0,files)} disabled={proofLoading!==null} title={files.map(file=>file.name).join("\n")} className="rounded-lg bg-cyan-300/10 px-2.5 py-1.5 text-[10px] font-bold text-cyan-200">{proofLoading!==null?"Открываю…":`📎 ${files.length}`}</button>;})():section==="postbacks"&&k==="status"?postbackStatus(v):valueCell(k,v)}</td>)}{section==="users"&&<td className="px-3 py-3"><button onClick={()=>void userAction(row,row.banned?"unban":"ban")} className={`rounded-lg px-3 py-2 text-[10px] font-bold ${row.banned?"bg-emerald-400/10 text-emerald-200":"bg-rose-400/10 text-rose-200"}`}>{row.banned?"Разблокировать":"Заблокировать"}</button></td>}{section==="offers"&&<td className="px-3 py-3"><div className="flex flex-wrap gap-1.5"><button onClick={()=>setOfferEdit({...row})} className="rounded-lg bg-violet-400/10 px-3 py-2 text-[10px] font-bold text-violet-200">Изменить</button><button onClick={()=>void toggleOffer(row)} className={`rounded-lg px-3 py-2 text-[10px] font-bold ${row.enabled?"bg-rose-400/10 text-rose-200":"bg-emerald-400/10 text-emerald-200"}`}>{row.enabled?"Выключить":"Включить"}</button></div></td>}{section==="applications"&&<td className="px-3 py-3"><div className="flex flex-wrap gap-1.5">{(row.status==="proof"||row.status==="hold")&&<button onClick={()=>void appAction(row,"confirm")} className="rounded-lg bg-emerald-400/10 px-2.5 py-2 text-[10px] font-bold text-emerald-200">Подтвердить</button>}{row.status==="proof"&&<button onClick={()=>void appAction(row,"hold")} className="rounded-lg bg-amber-400/10 px-2.5 py-2 text-[10px] font-bold text-amber-200">В холд</button>}{!["confirmed","paid","rejected","expired"].includes(String(row.status))&&<button onClick={()=>void appAction(row,"reject")} className="rounded-lg bg-rose-400/10 px-2.5 py-2 text-[10px] font-bold text-rose-200">Отклонить</button>}</div></td>}{section==="payouts"&&<td className="px-3 py-3"><div className="flex flex-wrap gap-1.5">{row.status==="pending"&&<button onClick={()=>void payoutAction(row,"take")} className="rounded-lg bg-cyan-300/10 px-3 py-2 text-[10px] font-bold text-cyan-200">Взять в работу</button>}{(row.status==="processing"||row.status==="review_required")&&<button onClick={()=>void payoutAction(row,"paid")} className="rounded-lg bg-emerald-400/10 px-3 py-2 text-[10px] font-bold text-emerald-200">Подтвердить перевод</button>}{["pending","processing","review_required"].includes(String(row.status))&&<button onClick={()=>void rejectPayout(row)} className="rounded-lg bg-rose-400/10 px-3 py-2 text-[10px] font-bold text-rose-200">Отказать и вернуть</button>}</div></td>}{section==="postbacks"&&<td className="px-3 py-3">{canBindPostback(row)?<button onClick={()=>void bindPostback(row)} className="rounded-lg bg-cyan-300/10 px-3 py-2 text-[10px] font-bold text-cyan-200">Привязать</button>:<span className="text-[10px] text-indigo-200/30">—</span>}</td>}</tr>)}</tbody></table>{(!viewRows||!viewRows.length)&&<div className="py-12 text-center text-sm text-indigo-200/40">{loading?"Загружаю…":section==="postbacks"?"По выбранным фильтрам postback-записей нет. Измени статус или запрос.":"В этом разделе пока нет записей"}</div>}</div>}
     {section==="broadcasts"&&<p className="mt-4 text-[11px] text-indigo-200/40">Рассылка выполняется в фоне. Если процесс сервера прервётся, кампания будет отмечена как прерванная; повторная отправка создаёт новую кампанию.</p>}
     {section==="payouts"&&<p className="mt-4 text-[11px] text-indigo-200/40">Реквизиты и расшифрованные телефоны намеренно не выводятся в общей таблице. Отказ возвращает зарезервированную сумму на баланс и записывается в журнал.</p>}
    </article>}
   </section>
  </div>
  {importOpen&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"><div className="max-h-[92vh] w-full max-w-3xl overflow-auto rounded-2xl border border-white/10 bg-[#10172d] p-5"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-black tracking-[.2em] text-cyan-300">ИМПОРТ ОФФЕРОВ</div><h2 className="mt-1 text-lg font-extrabold">CSV с предпросмотром</h2></div><button onClick={()=>{setImportOpen(false);setImportRows(null);}} className="rounded-lg bg-white/10 px-3 py-2 text-xs">Закрыть</button></div><textarea value={importText} onChange={e=>{setImportText(e.target.value);setImportRows(null);}} rows={8} placeholder={"code;name;bank;category;url;rate;condition;kind\nbank_x;Карта X;Банк;cards;https://partner.example/offer;1500;Условия;debit"} className="w-full resize-y rounded-xl border border-white/10 bg-black/20 p-3 font-mono text-xs leading-5 outline-none placeholder:text-indigo-200/25 focus:border-cyan-300/40"/><p className="mt-2 text-[11px] leading-5 text-indigo-200/45">Разделитель «;» или «,». Категории: cards, bk, mfo, cpl. Код латиницей; ставка становится выплатой сети и вознаграждением. Лимит — 500 строк.</p><div className="mt-3 flex flex-wrap items-center gap-2"><span className="mr-auto text-[10px] text-indigo-200/40">{importRows?`Создать: ${importRows.filter(row=>row.status==="create").length} · Обновить: ${importRows.filter(row=>row.status==="update").length} · Ошибок: ${importRows.filter(row=>row.status==="error").length}`:"Сначала проверь файл"}</span><button onClick={()=>void checkImport()} disabled={importBusy||!importText.trim()} className="rounded-xl border border-cyan-300/20 bg-cyan-300/10 px-4 py-2.5 text-xs font-bold text-cyan-200 disabled:opacity-40">{importBusy?"Проверяю…":"Проверить"}</button><button onClick={()=>void runImport()} disabled={importBusy||!importRows||importRows.some(row=>row.status==="error")} className="rounded-xl bg-emerald-400/15 px-5 py-2.5 text-xs font-extrabold text-emerald-200 disabled:opacity-40">{importBusy?"Импортирую…":"Импортировать"}</button></div>{importRows&&<div className="mt-4 overflow-x-auto"><table className="w-full min-w-[560px] border-collapse text-left text-xs"><thead><tr>{["Строка","Код","Название","Статус","Причина"].map(label=><th key={label} className="border-b border-white/10 px-3 py-3 font-bold text-indigo-200/45">{label}</th>)}</tr></thead><tbody>{importRows.map(row=><tr key={row.line} className="border-b border-white/[.05]"><td className="px-3 py-2.5 tabular-nums text-indigo-200/55">{row.line}</td><td className="px-3 py-2.5 font-mono text-[11px]">{row.code||"—"}</td><td className="max-w-[220px] truncate px-3 py-2.5" title={row.name}>{row.name||"—"}</td><td className="px-3 py-2.5">{importStatus(row.status)}</td><td className="px-3 py-2.5 text-indigo-200/60">{row.reason||"—"}</td></tr>)}</tbody></table></div>}</div></div>}
  {offerNew&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"><div className="max-h-[92vh] w-full max-w-2xl overflow-auto rounded-2xl border border-white/10 bg-[#10172d] p-5"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-black tracking-[.2em] text-cyan-300">НОВЫЙ ОФФЕР</div><h2 className="mt-1 text-lg font-extrabold">Добавить в каталог</h2></div><button onClick={()=>setOfferNew(null)} className="rounded-lg bg-white/10 px-3 py-2 text-xs">Закрыть</button></div><div className="grid gap-3 sm:grid-cols-2">{([["name","Название оффера"],["bank","Партнёр / бренд"],["code","Код (латиницей)"],["url","Партнёрская ссылка"],["rate","Ставка, ₽"],["hold","Холд, дней"]] as const).map(([key,label])=><label key={key} className="block text-[11px] text-indigo-200/60">{label}<input value={String(offerNew[key]??"")} onChange={e=>setOfferNew(old=>old?{...old,[key]:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-black/20 px-3 py-2.5 text-sm text-white outline-none focus:border-cyan-300/40"/></label>)}<label className="block text-[11px] text-indigo-200/60">Категория<select value={String(offerNew.category??"cpl")} onChange={e=>setOfferNew(old=>old?{...old,category:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-[#10172d] px-3 py-2.5 text-sm text-white outline-none"><option value="cpl">CPL-заявка</option><option value="cards">Карта</option><option value="mfo">Займ МФО</option><option value="bk">Букмекер</option></select></label>{String(offerNew.category)==="cards"&&<label className="block text-[11px] text-indigo-200/60">Тип карты<select value={String(offerNew.kind??"debit")} onChange={e=>setOfferNew(old=>old?{...old,kind:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-[#10172d] px-3 py-2.5 text-sm text-white outline-none"><option value="debit">Дебетовая</option><option value="credit">Кредитная</option></select></label>}</div><label className="mt-3 block text-[11px] text-indigo-200/60">Что нужно сделать<textarea rows={3} value={String(offerNew.condition??"")} onChange={e=>setOfferNew(old=>old?{...old,condition:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-black/20 p-3 text-sm text-white outline-none focus:border-cyan-300/40"/></label><p className="mt-3 text-[11px] text-indigo-200/45">Ставка сразу становится и выплатой сети, и вознаграждением пользователю. Код должен быть уникальным.</p><div className="mt-4 flex justify-end gap-2"><button onClick={()=>setOfferNew(null)} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs">Отмена</button><button onClick={()=>void createOffer()} disabled={offerSaving} className="rounded-xl bg-cyan-300/15 px-5 py-2.5 text-xs font-extrabold text-cyan-200 disabled:opacity-40">{offerSaving?"Создаю…":"Создать оффер"}</button></div></div></div>}
  {offerEdit&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-auto rounded-2xl border border-white/10 bg-[#10172d] p-5"><div className="mb-4 flex items-center justify-between"><div><div className="text-[10px] font-black tracking-[.2em] text-cyan-300">РЕДАКТОР ОФФЕРА</div><h2 className="mt-1 text-lg font-extrabold">{String(offerEdit.name??`Оффер #${offerEdit.id}`)}</h2></div><button onClick={()=>setOfferEdit(null)} className="rounded-lg bg-white/10 px-3 py-2 text-xs">Закрыть</button></div><div className="grid gap-3 sm:grid-cols-2">{([["name","Название"],["url","Партнёрская ссылка"],["hold","Холд, дней"],["age_min","Возраст от"],["age_max","Возраст до"],["network_payout","Выплата сети, ₽"],["user_reward","Награда пользователю, ₽"]] as const).map(([key,label])=><label key={key} className="block text-[11px] text-indigo-200/60">{label}<input value={String(offerEdit[key]??"")} onChange={e=>setOfferEdit(old=>old?{...old,[key]:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-black/20 px-3 py-2.5 text-sm text-white outline-none focus:border-cyan-300/40"/></label>)}</div>{([["action","Что нужно сделать"],["rules","Условия и ограничения"]] as const).map(([key,label])=><label key={key} className="mt-3 block text-[11px] text-indigo-200/60">{label}<textarea rows={3} value={String(offerEdit[key]??"")} onChange={e=>setOfferEdit(old=>old?{...old,[key]:e.target.value}:old)} className="mt-1 w-full rounded-xl border border-white/10 bg-black/20 p-3 text-sm text-white outline-none focus:border-cyan-300/40"/></label>)}<div className="mt-4 flex justify-end gap-2"><button onClick={()=>setOfferEdit(null)} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs">Отмена</button><button onClick={()=>void saveOffer()} disabled={offerSaving} className="rounded-xl bg-cyan-300/15 px-5 py-2.5 text-xs font-extrabold text-cyan-200 disabled:opacity-40">{offerSaving?"Сохраняю…":"Сохранить изменения"}</button></div></div></div>}
  {proofView&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4" onClick={()=>{URL.revokeObjectURL(proofView.url);setProofView(null);}}><div className="max-h-[90vh] w-full max-w-4xl overflow-auto rounded-2xl border border-white/10 bg-[#10172d] p-3" onClick={e=>e.stopPropagation()}><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div className="min-w-0"><b className="block truncate text-sm">{proofView.name}</b><span className="text-[10px] text-indigo-200/45">Файл {proofView.at+1} из {proofView.files.length} · {proofView.mime||"файл"}</span></div><div className="flex flex-wrap items-center gap-2">{proofView.files.length>1&&<button onClick={()=>void openProof(proofView.appId,(proofView.at+proofView.files.length-1)%proofView.files.length,proofView.files)} disabled={proofLoading!==null} title="Предыдущий файл" className="rounded-lg bg-white/10 px-3 py-2 text-xs disabled:opacity-40">←</button>}{proofView.files.length>1&&<button onClick={()=>void openProof(proofView.appId,(proofView.at+1)%proofView.files.length,proofView.files)} disabled={proofLoading!==null} title="Следующий файл" className="rounded-lg bg-white/10 px-3 py-2 text-xs disabled:opacity-40">→</button>}<a href={proofView.url} download={proofView.name} className="rounded-lg bg-cyan-300/10 px-3 py-2 text-xs font-bold text-cyan-200">Скачать</a><button onClick={()=>{URL.revokeObjectURL(proofView.url);setProofView(null);}} className="rounded-lg bg-white/10 px-3 py-2 text-xs">Закрыть</button></div></div>{proofView.mime==="application/pdf"?<iframe src={proofView.url} title={proofView.name} className="h-[75vh] w-full rounded-xl bg-white"/>:<img src={proofView.url} alt={proofView.name} className="mx-auto max-h-[75vh] max-w-full rounded-xl object-contain"/>}</div></div>}
  <footer className="mt-8 text-center text-[10px] text-indigo-300/30">Административный доступ контролируется сервером · Секретные платёжные данные не включены в списки</footer>
 </main>;
}
